import unittest
from interval_utils import merge_intervals


class MergeIntervalsTests(unittest.TestCase):
    def test_sorts_and_merges_overlapping_or_endpoint_sharing_intervals(self):
        intervals = [(8, 10), (1, 3), (3, 5), (4, 7)]
        self.assertEqual(merge_intervals(intervals), [(1, 7), (8, 10)])

    def test_keeps_disjoint_intervals_separate(self):
        self.assertEqual(merge_intervals([(5, 6), (1, 2)]), [(1, 2), (5, 6)])

    def test_empty_input_returns_an_empty_list(self):
        self.assertEqual(merge_intervals([]), [])

    def test_rejects_malformed_and_reversed_intervals(self):
        with self.assertRaises(ValueError):
            merge_intervals([(1, 2, 3)])
        with self.assertRaises(ValueError):
            merge_intervals([(4, 2)])

    def test_rejects_non_integer_endpoints(self):
        with self.assertRaises(TypeError):
            merge_intervals([(1, '3')])
        with self.assertRaises(TypeError):
            merge_intervals([(False, 3)])


if __name__ == '__main__':
    unittest.main()

