import unittest
from duration_format import format_duration


class FormatDurationTests(unittest.TestCase):
    def test_formats_zero_and_sub_hour_values(self):
        self.assertEqual(format_duration(0), '0:00:00')
        self.assertEqual(format_duration(65), '0:01:05')

    def test_formats_hours_and_preserves_remainder(self):
        self.assertEqual(format_duration(3605), '1:00:05')
        self.assertEqual(format_duration(7384), '2:03:04')

    def test_rejects_negative_values(self):
        with self.assertRaises(ValueError):
            format_duration(-1)

    def test_rejects_non_integer_values(self):
        for value in (1.5, '60', True):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    format_duration(value)


if __name__ == '__main__':
    unittest.main()
